// SignWell document.completed payload
const body = items[0].json.body || items[0].json;
if (body.event_type !== 'document_completed' && body.event !== 'document.signed') {
  // ignore non-completion events
  return [{ json: { skip: true } }];
}
const meta = body.metadata || body.data?.metadata || {};
return [{
  json: {
    document_id: body.document_id || body.data?.id,
    client_id: meta.client_id,
    tier: meta.tier,
    owner_voornaam: meta.owner_voornaam,
    owner_e164: meta.owner_e164,
    owner_email: meta.owner_email,
    bedrijfsnaam: meta.bedrijfsnaam,
    slug: meta.slug,
    provider: meta.provider,
    tally_short_url: meta.tally_short_url,
    loom_link: meta.loom_link,
    founder_voornaam: meta.founder_voornaam,
    founder_whatsapp: meta.founder_whatsapp,
    signed_at: body.completed_at || new Date().toISOString(),
    skip: false
  }
}];

